INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Zeigt traceroute immer alle Hops an?', 2, '[{"text": "Nein", "correct": true, "because": "Firewalls können blockieren"}, {"text": "Ja", "correct": false, "because": "Nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Information ist bei der Traceroute-Auswertung zentral?', 3, '[{"text": "Latenz pro Hop", "correct": true, "because": "Zeigt Verzögerung"}, {"text": "DNS-Namen", "correct": false, "because": "Optional"}, {"text": "Bandbreitenlimit", "correct": false, "because": "Nicht gemessen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Daten liefert traceroute?', 5, '[{"text": "Hop-IPs", "correct": true, "because": "Pfad zum Ziel"}, {"text": "Rundlaufzeiten", "correct": true, "because": "Latenz pro Hop"}, {"text": "Paketgröße", "correct": false, "because": "Nicht Standard"}, {"text": "DNS-Konfiguration", "correct": false, "because": "Andere Tools"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Traceroute misst Latenz. b) Es zeigt immer das Ziel.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ziel kann blockiert sein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Traceroute-Auswertung?', 4, '[{"text": "Hop-Latenz", "correct": false, "because": "Zeigt Engpässe"}, {"text": "Anzahl der Hops", "correct": false, "because": "Definiert Pfad"}, {"text": "Webserver-Status", "correct": true, "because": "Nicht Netzwerk-relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob traceroute Latenz pro Hop misst?', 2, '[{"text": "Ja", "correct": true, "because": "Teil der Ausgabe"}, {"text": "Nein", "correct": false, "because": "Standardfunktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ergebnis zeigt einen Engpass?', 3, '[{"text": "Hohe Latenz bei einem Hop", "correct": true, "because": "Verzögerung sichtbar"}, {"text": "Echo Reply vom Ziel", "correct": false, "because": "Erfolg"}, {"text": "Keine Antwort", "correct": false, "because": "Unterbrechung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente analysiere ich bei traceroute?', 5, '[{"text": "Latenzspitzen", "correct": true, "because": "Zeigt Probleme"}, {"text": "Hop-Reihenfolge", "correct": true, "because": "Pfadverlauf"}, {"text": "Datenpayload", "correct": false, "because": "Nicht analysiert"}, {"text": "Portnummern", "correct": false, "because": "Transportebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Traceroute zeigt Hops. b) Latenz ist immer gleich. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Latenz variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Traceroute-Auswertung?', 4, '[{"text": "Hop-Latenz", "correct": false, "because": "Zeigt Verzögerung"}, {"text": "Router-IPs", "correct": false, "because": "Definiert Pfad"}, {"text": "HTTP-Status", "correct": true, "because": "Anwendungsebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Misst traceroute die Bandbreite?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Latenz und Hops"}, {"text": "Ja", "correct": false, "because": "Andere Tools nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Zeichen zeigt eine Unterbrechung?', 4, '[{"text": "* * *", "correct": true, "because": "Keine Antwort"}, {"text": "Echo Reply", "correct": false, "because": "Erfolgreiche Antwort"}, {"text": "Low Latency", "correct": false, "because": "Kein Fehler"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass traceroute nur lokale Netze zeigt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Pfad bis Ziel"}, {"text": "Ja", "correct": false, "because": "Missverständnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Traceroute-Auswertung?', 3, '[{"text": "Latenzschwankungen", "correct": true, "because": "Zeigt Probleme"}, {"text": "DNS-Namen", "correct": false, "because": "Sekundär"}, {"text": "Paketgröße", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Traceroute zeigt Latenz. b) Hops sind optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Hops sind Kern"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Traceroute-Auswertung?', 5, '[{"text": "Pfadanalyse", "correct": true, "because": "Zeigt Hops"}, {"text": "Engpass-Erkennung", "correct": true, "because": "Latenz sichtbar"}, {"text": "IP-Zuweisung", "correct": false, "because": "DHCP-Aufgabe"}, {"text": "Datenübertragung", "correct": false, "because": "Nur Diagnose"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Traceroute-Auswertung unwichtig?', 3, '[{"text": "Hop-Reihenfolge", "correct": false, "because": "Pfadverlauf"}, {"text": "Latenzwerte", "correct": false, "because": "Zeigt Probleme"}, {"text": "Web-UI", "correct": true, "because": "Nicht Netzwerk-relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann traceroute ohne Latenz ausgewertet werden?', 3, '[{"text": "Nein", "correct": true, "because": "Latenz ist zentral"}, {"text": "Ja", "correct": false, "because": "Kern der Analyse"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob traceroute Unterbrechungen zeigt?', 2, '[{"text": "Ja", "correct": true, "because": "Timeouts sichtbar"}, {"text": "Nein", "correct": false, "because": "Teil der Ausgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ergebnis zeigt das Ziel erreicht?', 4, '[{"text": "Latenz vom Ziel", "correct": true, "because": "Ende des Pfads"}, {"text": "Time Exceeded", "correct": false, "because": "Hop-Limit"}, {"text": "* * *", "correct": false, "because": "Keine Antwort"}]');
